"""Original finite diagrams; the shared reader supplies text/print transcripts."""
def D(identifier,chapter,title,assumptions,nodes,edges,frames,takeaway,sources):
    ids=[n[0] for n in nodes]
    steps=[]
    for name,actor,explanation,values,focus,active,before,after in frames:
        steps.append(dict(title=name,actor=actor,explanation=explanation,states=dict(zip(ids,values)),focus=focus.split(),active=active.split(),fields=[dict(name='Изменение',before=before,after=after,why=explanation)],bands=[dict(label='Результат шага',value=after,detail=explanation)]))
    return dict(id=identifier,volume='operating-systems',chapter=chapter,anchor=chapter,title=title,intro='Выберите шаг и проследите, кто изменил состояние. Полная история доступна также текстом и при печати.',assumptions=assumptions,nodes=[dict(id=i,label=l,sub=s) for i,l,s in nodes],edges=[dict(id=i,**{'from':a,'to':b},label=l) for i,a,b,l in edges],steps=steps,takeaway=takeaway,sources=sources,insert_before='<h2>Проверяемая модель</h2>')
